167 |     function _updateOutstandingDebt()
168 |         internal
169 |         returns (uint256 principal, uint256 interest)
170 |     {
171 |         // use full length not count because positions might not be packed in order
172 |         uint256 len = ids.length;
173 |         if (len == 0) return (0, 0);
174 | 
175 |         bytes32 id;
176 |         address oracle_ = address(oracle);  // gas savings
177 |         address interestRate_ = address(interestRate); // gas savings
178 |         
179 |         for (uint256 i; i < len; ++i) {
180 |             id = ids[i];
181 | 
182 |             // null element in array from closing a position. skip for gas savings
183 |             if(id == bytes32(0)) { continue; }
184 | 
185 |             (Credit memory c, uint256 _p, uint256 _i) = CreditLib.getOutstandingDebt(
186 |               credits[id],
187 |               id,
188 |               oracle_,
189 |               interestRate_
190 |             );
191 |             // update total outstanding debt
192 |             principal += _p;
193 |             interest += _i;
194 |             // save changes to storage
195 |             credits[id] = c;
196 |         }
197 |     }
