199 |     /// see ILineOfCredit.accrueInterest
200 |     function accrueInterest() external override returns(bool) {
201 |         uint256 len = ids.length;
202 |         bytes32 id;
203 |         for (uint256 i; i < len; ++i) {
204 |           id = ids[i];
205 |           Credit memory credit = credits[id];
206 |           credits[id] = _accrue(credit, id);
207 |         }
208 |         
209 |         return true;
210 |     }
