212 |     /**
213 |       @notice - accrues token demoninated interest on a lender's position.
214 |       @dev MUST call any time a position balance or interest rate changes
215 |       @param credit - the lender position that is accruing interest
216 |       @param id - the position id for credit position
217 |     */
218 |     function _accrue(Credit memory credit, bytes32 id) internal returns(Credit memory) {
219 |       return CreditLib.accrue(credit, id, address(interestRate));
220 |     }
